python3 -c "
import json, collections
p='data/trajectories_v1_01.jsonl'
ct=collections.Counter(); surf=collections.Counter()
err=collections.Counter(); tot=collections.Counter()
for line in open(p):
    d=json.loads(line)
    names={t.get('name') for t in (d.get('tools') or [])}
    fam='claude' if d['model'].startswith('claude') else 'gpt'
    dialect='bash+file_*' if 'bash' in names else ('shell+apply_patch' if 'shell_command' in names else '?')
    s='teams' if any('msteams' in n or 'channel' in n for n in names) else 'slack'
    ct[(fam,dialect)]+=1; surf[(fam,s)]+=1
    # error signal on tool outputs
    pending={}
    for it in d.get('input',[]):
        if it.get('type') in ('function_call','custom_tool_call'):
            pending[it.get('call_id') or it.get('id')]=it.get('name')
        elif it.get('type') in ('function_call_output','custom_tool_call_output'):
            nm=pending.get(it.get('call_id') or it.get('id'),'?')
            out=json.dumps(it.get('output'))[:4000].lower()
            tot[nm]+=1
            if any(k in out for k in ('error','traceback','command failed','no such file','exit code: 1','permission denied')):
                err[nm]+=1
print('--- coding dialect x model family (requests)')
for k,v in sorted(ct.items()): print(f'  {k[0]:7} {k[1]:18} {v}')
print('--- surface x model family (requests)')
for k,v in sorted(surf.items()): print(f'  {k[0]:7} {k[1]:6} {v}')
print('--- tool outputs w/ error-ish text (summed over re-sent history)')
for n,t in tot.most_common(12):
    print(f'  {n:32} {err[n]:6}/{t:<7} {100*err[n]/t:5.1f}%')
"

